input.command:
ip -br addr show; echo "---"; nmcli device status; echo "---"; curl -s --max-time 4 --interface enp129s0 http://192.168.110.1 -o /dev/null -w "enp129->gateway: %{http_code}
" 2>&1; curl -s --max-time 4 --interface wlp130s0 http://192.168.110.1 -o /dev/null -w "wifi->gateway: %{http_code}
" 2>&1; curl -s --max-time 5 --interface enp129s0 https://www.baidu.com -o /dev/null -w "enp129 baidu: %{http_code}
" 2>&1; curl -s --max-time 5 --interface wlp130s0 https://www.baidu.com -o /dev/null -w "wifi baidu: %{http_code}
" 2>&1
